        }
        if (list[cdp].next != 0) {                              
            list[list[cdp].next].prev = list[cdp].prev;         
        } else {                                                
            last[owns[cdp]] = list[cdp].prev;                   
        }
        if (first[owns[cdp]] == cdp) {                          
            first[owns[cdp]] = list[cdp].next;                  
        }
        count[owns[cdp]] = sub(count[owns[cdp]], 1);


        owns[cdp] = dst;


